style.css:
@-moz-document domain("youtube.com") {
/* --- 1. CORE VARIABLES --- */
    :root {
        --cyber-red: #ff003c;
        --cyber-dark: #050505;
        --neon-glow: 0 0 12px rgba(255, 0, 60, 0.8);
    }

    /* --- 2. LIVE BACKGROUND (NO SCANLINES) --- */
    html, [dark], ytd-app, #master-container {
        background: url("https://i.pinimg.com/1200x/d1/da/63/d1da635864ae706e228343227a61a28e.jpg") no-repeat center center fixed !important;
        background-size: cover !important;
        --yt-spec-base-background: transparent !important;
    }

    /* --- 3. HEXAGONAL SEARCH BAR --- */
    ytd-searchbox {
        position: relative;
        z-index: 2002;
    }

    #search-form #container {
        background: rgba(0, 0, 0, 0.9) !important;
        border: 2px solid var(--cyber-red) !important;
        border-radius: 0px !important;
        clip-path: polygon(15px 0, 100% 0, 100% calc(100% - 15px), calc(100% - 15px) 100%, 0 100%, 0 15px) !important;
        box-shadow: var(--neon-glow) !important;
    }

    #search-icon-legacy {
        background: var(--cyber-red) !important;
        border: none !important;
        border-radius: 0px !important;
        margin-left: 5px !important;
        clip-path: polygon(10px 0, 100% 0, 100% 100%, 0 100%, 0 10px) !important;
    }

    #search-icon-legacy yt-icon {
        color: #000 !important;
    }

    /* --- 4. NEON ICONS & LOGO --- */
    yt-icon, .yt-spec-icon-shape svg {
        fill: var(--cyber-red) !important;
        color: var(--cyber-red) !important;
        filter: drop-shadow(0 0 4px var(--cyber-red));
    }

    ytd-topbar-logo-renderer #logo-icon {
        filter: drop-shadow(0 0 5px var(--cyber-red)) hue-rotate(330deg) saturate(5) !important;
    }

    /* --- 5. CHIP BUTTONS (GLOBAL) --- */
    yt-button-shape, button.yt-spec-button-shape-next, .ytp-button {
        background: rgba(10, 10, 10, 0.8) !important;
        border: 1px solid var(--cyber-red) !important;
        border-radius: 0px !important;
        clip-path: polygon(6px 0%, 100% 0%, 100% calc(100% - 6px), calc(100% - 6px) 100%, 0% 100%, 0% 6px) !important;
        transition: 0.2s !important;
    }

    yt-button-shape:hover, .ytp-button:hover {
        background: var(--cyber-red) !important;
        color: #000 !important;
        box-shadow: 0 0 20px var(--cyber-red) !important;
        transform: scale(1.05);
    }

    .ytp-button:hover svg path {
        fill: #fff !important;
        filter: drop-shadow(0 0 8px #fff);
    }

    /* --- 6. SUGGESTION CHIPS (HOME PAGE) --- */
    yt-chip-cloud-chip-renderer {
        background: rgba(0, 0, 0, 0.8) !important;
        border: 1px solid var(--cyber-red) !important;
        border-radius: 0px !important;
        color: var(--cyber-red) !important;
        text-transform: uppercase;
        font-weight: bold;
        clip-path: polygon(5px 0, 100% 0, 100% calc(100% - 5px), calc(100% - 5px) 100%, 0 100%, 0 5px) !important;
    }

    yt-chip-cloud-chip-renderer:hover {
        background: var(--cyber-red) !important;
        color: #000 !important;
        box-shadow: 0 0 15px var(--cyber-red);
    }

    yt-chip-cloud-chip-renderer[selected] {
        background: #fff !important;
        color: #000 !important;
        border: 1px solid #fff !important;
        box-shadow: 0 0 10px #fff;
    }

    /* --- 7. PLAYER SETTINGS MENU --- */
    .ytp-popup, .ytp-panel-menu {
        background: rgba(10, 10, 10, 0.95) !important;
        border: 1px solid var(--cyber-red) !important;
        border-radius: 0px !important;
        backdrop-filter: blur(5px);
    }

    .ytp-menuitem:hover {
        background-color: var(--cyber-red) !important;
    }

    .ytp-menuitem-label, .ytp-menuitem-content {
        color: #fff !important;
        font-family: monospace !important;
    }

    .ytp-menuitem:hover .ytp-menuitem-label {
        color: #000 !important;
        font-weight: bold;
    }

    /* --- 8. LASER SEEK BAR ANIMATION --- */
    .ytp-play-progress {
        background: linear-gradient(90deg, #500000, var(--cyber-red)) !important;
        box-shadow: 0 0 20px var(--cyber-red), 0 0 10px #fff;
        height: 100% !important;
    }

    .ytp-scrubber-button {
        background: #000 !important;
        border: 2px solid #fff !important;
        box-shadow: 0 0 15px var(--cyber-red);
        border-radius: 0px !important;
        width: 18px !important;
        height: 18px !important;
        transform: rotate(45deg) scale(1.2) !important;
        transition: 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275);
    }

    .ytp-scrubber-button:hover {
        background: #fff !important;
        border-color: var(--cyber-red) !important;
        box-shadow: 0 0 30px var(--cyber-red), 0 0 50px var(--cyber-red);
        transform: rotate(225deg) scale(1.5) !important;
    }
}
